import { buildTree, diff3, encodeDeltaFrame } from './sync/merkle-dag-diff';

export interface Document {
  id: string;
  body: string;
}

export interface SyncEngineOptions {
  nodeId: number;
  maxDriftMs?: number;
}

export class SyncEngine {
  readonly clock: HybridLogicalClock;
  readonly docs = new LwwElementSet<Document>((doc) => doc.id);
  private readonly versions = new Map<string, HlcTimestamp>();

  constructor(options: SyncEngineOptions) {
    this.clock = new HybridLogicalClock(options.nodeId, { maxDriftMs: options.maxDriftMs ?? 60_000 });
  }

  upsert(doc: Document): void {
    const ts = this.clock.tick();
    this.docs.add(doc, ts);
    this.versions.set(doc.id, ts);
  }

  remove(doc: Document): void {
    const ts = this.clock.tick();
    this.docs.remove(doc, ts);
    this.versions.set(doc.id, ts);
  }

  applyRemote(delta: Delta<Document>[]): number {
    for (const { entry } of delta) {
      const stamp = entry.removed ?? entry.added;
      if (stamp) this.clock.receive(stamp);
    }
    return this.docs.merge(delta);
  }

  reconcile(peerVersions: Map<string, HlcTimestamp>) {
    const plan = diff3(undefined, buildTree(this.versions), buildTree(peerVersions));
    const packed = new Map([...this.versions].map(([key, ts]) => [key, BigInt(ts.wallMs)]));
    return { plan, frame: encodeDeltaFrame(plan.missingRemotely, packed) };
  }
}
