export interface Totals {
  subtotal: number;
  taxTotal: number;
  discountTotal: number;
  total: number;
}

const DISCOUNTS: Record<string, { percent?: number; flat?: number; minSubtotal?: number }> = {
  WELCOME10: { percent: 0.1 },
  ANNUAL20: { percent: 0.2, minSubtotal: 1000 },
  PARTNER250: { flat: 250, minSubtotal: 2500 },
};

const roundCents = (value: number): number => Math.round(value * 100) / 100;

export function lineTotal(item: LineItem): number {
  return roundCents(item.quantity * item.unitPrice);
}

export function computeTotals(items: LineItem[], discountCode?: string): Totals {
  const subtotal = roundCents(items.reduce((sum, item) => sum + lineTotal(item), 0));
  const taxTotal = roundCents(items.reduce((sum, item) => sum + lineTotal(item) * (item.taxRate ?? 0), 0));
  let discountTotal = 0;
  const discount = discountCode ? DISCOUNTS[discountCode.toUpperCase()] : undefined;
  if (discount && subtotal >= (discount.minSubtotal ?? 0)) {
    discountTotal = discount.percent ? roundCents(subtotal * discount.percent) : discount.flat ?? 0;
  }
  if (discountTotal > subtotal) discountTotal = subtotal;
  return { subtotal, taxTotal, discountTotal, total: roundCents(subtotal + taxTotal - discountTotal) };
}

export function isOverdue(invoice: Invoice, today: Date = new Date()): boolean {
  if (invoice.status === 'paid' || invoice.status === 'void') return false;
  return new Date(invoice.dueDate).getTime() < today.getTime();
}

export function formatMoney(amount: number, currency: string): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);
}

export function validateInvoice(items: LineItem[], issueDate: string, dueDate: string): string[] {
  const errors: string[] = [];
  if (items.length === 0) errors.push('Add at least one line item.');
  if (items.some((item) => item.quantity <= 0)) errors.push('Quantities must be positive.');
  if (items.some((item) => item.unitPrice < 0)) errors.push('Unit prices cannot be negative.');
  if (new Date(dueDate) < new Date(issueDate)) errors.push('Due date must be on or after the issue date.');
  return errors;
}
